using System.Diagnostics;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text.Json;
using Tertius.Benchmarks;
using Tertius.Rendering;

internal static class CpuPreparationProbe
{
    public static void Main(string[] args)
    {
        const int warmUp = 64;
        const int samples = 128;
        string[] maps = ["off", "one-face", "six-faces", "four-maps-one-face", "four-maps-24-faces"];
        var rows = new List<object>();
        foreach (string map in maps)
        {
            var fixture = new SceneBatcherBenchmarks { Map = map, Posed = 0 };
            fixture.Setup();
            for (int draw = 0; draw < warmUp; draw++)
                fixture.Prepare();
            var milliseconds = new double[samples];
            long before = GC.GetAllocatedBytesForCurrentThread();
            for (int draw = 0; draw < samples; draw++)
            {
                long start = Stopwatch.GetTimestamp();
                fixture.Prepare();
                milliseconds[draw] = 1000.0 * (Stopwatch.GetTimestamp() - start) / Stopwatch.Frequency;
            }
            long bytes = GC.GetAllocatedBytesForCurrentThread() - before;
            fixture.Cleanup();
            rows.Add(new { Map = map, Instances = 20000, Posed = 0, WarmUp = warmUp, Samples = samples,
                Milliseconds = milliseconds, AllocatedBytesOnCallingThread = bytes });
        }
        File.WriteAllText(args[1], JsonSerializer.Serialize(new
        {
            Variant = args[0],
            Utc = DateTimeOffset.UtcNow,
            Runtime = RuntimeInformation.FrameworkDescription,
            Architecture = RuntimeInformation.ProcessArchitecture.ToString(),
            Stopwatch.Frequency,
            RendererSha256 = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(typeof(VulkanRenderer).Assembly.Location))),
            RunnerSha256 = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(Assembly.GetExecutingAssembly().Location))),
            Rows = rows
        }));
    }
}

